 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    fives = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    # The source 5 is the one embedded in the patterned object; other 5s are targets.
    def nearby(r, c):
        return sum(1 for rr in range(max(0, r-4), min(h, r+5))
                   for cc in range(max(0, c-4), min(w, c+5))
                   if grid[rr][cc] != 0 and (rr, cc) != (r, c))
    src = max(fives, key=lambda p: nearby(*p))
    sr, sc = src
    offsets = [(r-sr, c-sc, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != 0 and (r, c) != src]
    for tr, tc in fives:
        if (tr, tc) == src:
            continue
        out[tr][tc] = 0
        for dr, dc, color in offsets:
            rr, cc = tr+dr, tc+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
